async def read_one(session, uri):
    result = await session.read_resource(uri)
    for item in result.contents:
        if item.text is not None:
            print("text resource:", item.text[:100])
        elif item.blob is not None:
            print("binary resource, mimeType", item.mimeType)
    return result

def build_context_message(resource_content):
    if resource_content.text is not None:
        body = resource_content.text
    else:
        body = "[binary content, mimeType: " + resource_content.mimeType + "]"
    return {
        "role": "user",
        "content": "Resource " + resource_content.uri + " contains:\n" + body
    }

