class ResourceCache:
    def __init__(self, ttl_seconds=60):
        self.ttl = ttl_seconds
        self.store = {}

    def get(self, uri):
        entry = self.store.get(uri)
        if entry is None:
            return None
        content, cached_at = entry
        if time.time() - cached_at > self.ttl:
            return None
        return content

    def set(self, uri, content):
        self.store[uri] = (content, time.time())
